<script setup>defineProps({product:Object})</script><template><article class="product-card"><RouterLink :to="`/product/${product.id}`"><div class="product-image"><span v-if="product.badge" class="badge">{{product.badge}}</span><div class="device-shape"></div></div><div class="product-meta"><small>{{product.brand}}</small><h3>{{product.name}}</h3><p>{{product.spec}}</p><strong>${{product.price.toLocaleString()}}</strong></div></RouterLink><button class="button button-dark" @click.prevent="$emit('add',product)">{{product.stock===0?'Notify Me':'Add'}}</button></article></template>
